"""Build a compact dated evidence profile; no live actions or automatic thresholds."""
import json
from pathlib import Path
P=Path(__file__).resolve().parent.parent/'outputs'
def get(n):return json.loads((P/n).read_text(encoding='utf-8'))
s=get('rosery-economics-q3-shopify-2026-10-19.json');tw=get('rosery-economics-triplewhale-observed-2026-10-19.json');c=get('rosery-economics-cohorts-2026-10-19.json')
profile={'business':'ROSERY','shop':'21cc82-3.myshopify.com','as_of':'2026-10-19','currency':'ILS','period':'2026-07-01/2026-09-30','status':'evidence_profile_estimates_not_operating_limits','sources':[s['query'],'Triple Whale visible Q3 Summary',c['query']],'inputs':{'packaging_ils':{'value':4,'status':'user supplied'},'vat_rate':{'value':0.18,'status':'user operating assumption; Shopify records near-zero taxes, do not treat recorded zero as zero liability'},'courier_ils':{'value':25,'status':'historical estimate, not verified'},'processing_rate':{'value':0.02,'status':'historical estimate, not verified'}},'segments':{},'automatic_scale_or_pause_thresholds':None,'new_customer_target_cac':None,'returning_customer_target_cpa':None}
for r in s['rows']:
 typ,n,customers,net,shipping,cogs,covered,uncovered=r;n=int(n);net=float(net);shipping=float(shipping);cogs=float(cogs);sales=net+shipping
 profile['segments'][typ]={'orders':n,'customers':int(customers),'net_product_sales':net,'shipping_revenue':shipping,'recorded_cogs':cogs,'product_revenue_per_order':net/n,'recorded_cogs_per_order':cogs/n,'sales_plus_shipping_per_order':sales/n,'before_ad_contribution_scenario_vat18_included':((sales/1.18-cogs)/n)-4-25-0.02*sales/n,'before_ad_contribution_scenario_tax_already_excluded':(sales-cogs)/n-4-25-0.02*sales/n,'scenario_status':'illustrative break-even, not verified profit or spending authorization; cost VAT basis, reversals and actual fees need reconciliation','unrecorded_cost_sales':float(uncovered),'cost_coverage_reconciliation_gap':float(covered)+float(uncovered)-net}
profile['acquisition']={'blended_all_channel_spend':tw['blended_spend'],'new_customers':1472,'blended_ncpa_recomputed':tw['blended_spend']/1472,'dashboard_new_customer_cpa':tw['new_customer_cpa_display'],'dashboard_ltv':tw['ltv_display'],'dashboard_ltv_to_general_cpa':tw['ltv_to_cpa_display'],'same_display_ltv_divided_by_new_cpa':tw['ltv_display']/tw['new_customer_cpa_display'],'last_ratio_status':'diagnostic arithmetic only, not matched-cohort contribution LTV:CAC; spend includes all channels and organic new customers in denominator'}
profile['cohorts']=[{'acquisition_month':r[0],'customers':int(r[1]),'lifetime_orders':int(r[2]),'lifetime_revenue':float(r[3]),'observed_revenue_per_customer':float(r[3])/int(r[1]),'orders_per_customer':int(r[2])/int(r[1])} for r in c['rows']]
profile['cohort_limits']=['Lifetime-to-date values, unequal maturation; not 90/180-day LTV.','No contribution costs by customer cohort fetched.','477 returning orders / 1949 total orders is order mix, not cohort repeat rate.','Returning customer paid-attributed CPA is not repeat-order incrementality.']
profile['missing_for_verified_limits']=['Actual courier/processing/return handling costs and their VAT basis','Reconciliation of recorded COGS coverage against net sales and reversal timing','Fixed-horizon cohort contribution and retention marketing spend','Cash payback horizon and profit/fixed-cost reserve; no universal LTV:CAC target imposed']
(P/'rosery-business-economics-profile-2026-10-19.json').write_text(json.dumps(profile,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'new_customer_cpa':profile['acquisition']['blended_ncpa_recomputed'],'scenarios':{k:round(v['before_ad_contribution_scenario_vat18_included'],2) for k,v in profile['segments'].items()},'cohort_ltv_range':[min(x['observed_revenue_per_customer'] for x in profile['cohorts']),max(x['observed_revenue_per_customer'] for x in profile['cohorts'])]}))
if len(profile['segments'])!=2 or profile['automatic_scale_or_pause_thresholds'] is not None:raise ValueError('Unsafe profile')
